import{_ as p,o as a,c as o,a2 as t}from"./chunks/framework.Bg-Zxr5O.js";const i=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/System-Variables.md","filePath":"manual-zh/System-Variables.md","lastUpdated":1785684581000}'),d={name:"manual-zh/System-Variables.md"};function c(s,e,r,_,n,l){return a(),o("div",null,[...e[0]||(e[0]=[t('<h4 id="_6-7-2-pspp-自动定义的变量" tabindex="-1">6.7.2 PSPP 自动定义的变量 <a class="header-anchor" href="#_6-7-2-pspp-自动定义的变量" aria-label="Permalink to &quot;6.7.2 PSPP 自动定义的变量&quot;">​</a></h4><p>共有七个系统变量。它们不同于普通变量，因为系统变量并非总是被存储。它们只能在表达式中使用。这些系统变量的值与输出格式不可修改，下面分别描述。</p><p><code>$CASENUM</code></p><p>当前个案的个案序号。随着个案被重新排列，该值会发生变化。</p><p><code>$DATE</code></p><p>PSPP 进程启动的日期，格式为 A9，遵循 <code>DD-MMM-YY</code> 模式。</p><p><code>$DATE11</code></p><p>PSPP 进程启动的日期，格式为 A11，遵循 <code>DD-MMM-YYYY</code> 模式。</p><p><code>$JDATE</code></p><p>1582 年 10 月 15 日与 PSPP 进程启动时刻之间相隔的天数。</p><p><code>$LENGTH</code></p><p>页长，以行为单位，格式为 F11。</p><p><code>$SYSMIS</code></p><p>系统缺失值，格式为 F1。</p><p><code>$TIME</code></p><p>1582 年 10 月 14 日午夜与活动数据集被读取时刻之间相隔的秒数，格式为 F20。</p><p><code>$WIDTH</code></p><p>页宽，以字符为单位，格式为 F3。</p>',18)])])}const S=p(d,[["render",c]]);export{i as __pageData,S as default};
